import base64, gzip, pathlib, subprocess

PAYLOAD = ""
patch = gzip.decompress(base64.b64decode(PAYLOAD))
path = pathlib.Path("/tmp/front_gate.patch")
path.write_bytes(patch)
subprocess.run(["git", "apply", "--check", str(path)], check=True)
subprocess.run(["git", "apply", str(path)], check=True)
print(f"Applied verified front-gate patch: {len(patch)} bytes")
